import{_ as o,o as i,c as t,ag as a}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-10-08（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-08.md","filePath":"topics/biomedicine/science-daily-2026-10-08.md"}'),c={name:"topics/biomedicine/science-daily-2026-10-08.md"};function n(s,e,r,d,l,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="科学日报-·-2026-10-08-生物医学" tabindex="-1">科学日报 · 2026-10-08（生物医学） <a class="header-anchor" href="#科学日报-·-2026-10-08-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-10-08（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> — 第31期</p></blockquote><hr><h2 id="随人类迁徙、在工业化人群中消失的肠道微生物-nature" tabindex="-1">随人类迁徙、在工业化人群中消失的肠道微生物（Nature） <a class="header-anchor" href="#随人类迁徙、在工业化人群中消失的肠道微生物-nature" aria-label="Permalink to &quot;随人类迁徙、在工业化人群中消失的肠道微生物（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> ｜ DOI: 10.1038/s41586-026-11106-1</p></blockquote><ul><li>背景：许多非工业化人群中常见的肠道微生物，在工业化人群里已经消失或灭绝；哪些是人类肠道的<strong>长期居民</strong>、是否与人类共同演化，此前难厘清（微生物演化复杂 + 群落组成可塑）。</li><li>方法：对玻利维亚 <strong>Tsimane 农耕人群</strong>做深度宏基因组测序，并与坦桑尼亚 <strong>Hadza 狩猎采集人群</strong>比对。</li><li>数据：两群体祖先已分离<strong>数万年</strong>，仍共享 <strong>1231 个微生物物种</strong>，其中大多数在工业化人群中罕见或缺失。</li><li>结论/意义：这些是<strong>随人类迁徙传播、长期共居</strong>于人类肠道的物种；为评估微生物多样性丧失如何影响健康、重建人类—微生物共进化史提供了关键基线。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第31期 科学板块</p></blockquote><p>关键词：肠道微生物组、宏基因组、Tsimane、Hadza、工业化、多样性丧失、共进化、人类迁徙 关联：<code>topics/biomedicine/science-daily-2026-09-22.md</code>（sOrganellomics 空间图谱：功能基线的另一条线）、<code>topics/paleoanthropology/</code>（人群迁徙与古DNA）、<code>topics/paleontology/science-daily-2026-10-08.md</code>（同日：进化视角的生命史）</p>',9)])])}const _=o(c,[["render",n]]);export{u as __pageData,_ as default};
